import React, { useState, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import Console from './components/Console';
import RunButton from './components/RunButton';
import './App.css';

function App() {
  const [code, setCode] = useState('// Your banana code goes here 🍌');
  const [output, setOutput] = useState('');
  const [waitingForInput, setWaitingForInput] = useState(false);
  const [inputPrompt, setInputPrompt] = useState('');
  const [currentSessionId, setCurrentSessionId] = useState(null);
  const [userInput, setUserInput] = useState('');
  const pollingIntervalRef = useRef(null);

  const stopPolling = () => {
    if (pollingIntervalRef.current) {
      clearInterval(pollingIntervalRef.current);
      pollingIntervalRef.current = null;
    }
  };

  const pollForStatus = async (sessionId) => {
    try {
      const response = await fetch(`http://localhost:3001/api/status/${sessionId}`);
      const data = await response.json();

      if (data.complete) {
        stopPolling();
        setOutput(data.output || '(No output - program executed successfully)');
        setWaitingForInput(false);
        setCurrentSessionId(null);
        return;
      }

      // Update output as it comes in
      if (data.output) {
        setOutput(data.output);
      }

      // Check if input is needed
      if (data.needsInput) {
        setWaitingForInput(true);
        setInputPrompt(data.prompt || 'Input needed');
        stopPolling();
      }
    } catch (error) {
      console.error('Polling error:', error);
      stopPolling();
    }
  };

  const handleRun = async () => {
    setOutput('Executing...');
    setWaitingForInput(false);
    setUserInput('');
    stopPolling();

    try {
      const response = await fetch('http://localhost:3001/api/run', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ code }),
      });

      const data = await response.json();

      if (response.ok) {
        // Update output
        if (data.output) {
          setOutput(data.output);
        }

        // Check if input is needed
        if (data.needsInput) {
          setWaitingForInput(true);
          setInputPrompt(data.prompt || 'Input needed');
          setCurrentSessionId(data.sessionId);
        } else if (data.complete) {
          // Execution completed
          const outputText = (data.output || '').trim();
          setOutput(outputText || '(No output - program executed successfully)');
        } else if (data.sessionId) {
          // Process is running, start polling
          setCurrentSessionId(data.sessionId);
          pollingIntervalRef.current = setInterval(() => {
            pollForStatus(data.sessionId);
          }, 500);
        }
      } else {
        const errorMsg = data.error || 'Unknown error';
        const outputText = data.output || '';
        setOutput(`🚫 Error: ${errorMsg}${outputText ? '\n\n' + outputText : ''}`);
      }
    } catch (error) {
      setOutput(`🚫 Error: Failed to connect to backend.\nMake sure the backend server is running on http://localhost:3001\n\nError details: ${error.message}`);
    }
  };

  const handleInputSubmit = async (e) => {
    e.preventDefault();
    if (!currentSessionId || !userInput.trim()) {
      return;
    }

    setWaitingForInput(false);
    setOutput(prev => prev + '\n> ' + userInput);

    try {
      // Send input to continue execution
      const response = await fetch('http://localhost:3001/api/run', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ 
          sessionId: currentSessionId,
          input: userInput.trim()
        }),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        // Input provided, start polling for output
        setUserInput('');
        pollingIntervalRef.current = setInterval(() => {
          pollForStatus(currentSessionId);
        }, 500);
      } else {
        setOutput(prev => prev + '\n🚫 Error providing input');
      }
    } catch (error) {
      setOutput(prev => prev + '\n🚫 Error: ' + error.message);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>🍌 Banana IDE 🍌</h1>
      </header>
      <main className="ide-container">
        <CodeEditor code={code} setCode={setCode} />
        <RunButton onRun={handleRun} />
        {waitingForInput && (
          <div className="input-prompt">
            <form onSubmit={handleInputSubmit}>
              <label>
                {inputPrompt}
                <input
                  type="text"
                  value={userInput}
                  onChange={(e) => setUserInput(e.target.value)}
                  placeholder="Enter input..."
                  autoFocus
                />
              </label>
              <button type="submit">Submit</button>
            </form>
          </div>
        )}
        <Console output={output} />
      </main>
      <footer className="emoji-key-container">
        <h2>Emoji Language Key</h2>
        <ul className="emoji-key-list">
          <li><code>🍌</code> - Statement Terminator</li>
          <li><code>🐵</code> - Print to console</li>
          <li><code>🌴</code> - Declare a variable</li>
          <li><code>🥥</code> - String literal wrapper</li>
          <li><code>➡️</code> - Assignment operator</li>
          <li><code>➕</code> - Addition</li>
          <li><code>➖</code> - Subtraction</li>
          <li><code>🔁</code> - Loop construct</li>
          <li><code>❓</code> - Conditional (if) statement</li>
        </ul>
      </footer>
    </div>
  );
}

export default App;
